 63→type droidCustomModel struct {
 64→	DisplayName    string `json:"displayName"`
 65→	Model          string `json:"model"`
 66→	BaseURL        string `json:"baseUrl"`
 67→	APIKey         string `json:"apiKey"`
 68→	Provider       string `json:"provider"`
 69→	MaxOutputToken int    `json:"maxOutputTokens"`
 70→}
