 72→const (
 73→	// Droid v0.63+ expects custom model selection using custom:<model-id>.
 74→	// The displayName in settings is not accepted by --model.
 75→	droidCustomModelDisplayName = "claude-haiku-custom"
 76→	droidCustomModelBaseID      = "claude-haiku-4-5-20251001"
 77→	defaultDroidModel           = "custom:" + droidCustomModelBaseID
 78→)
