 80→func (d *Droid) Bootstrap() error {
 81→	apiKey := os.Getenv("ANTHROPIC_API_KEY")
 82→	if apiKey == "" {
 83→		return nil
 84→	}
 85→
 86→	home, err := os.UserHomeDir()
 87→	if err != nil {
 88→		return fmt.Errorf("get home dir: %w", err)
 89→	}
 90→	dir := filepath.Join(home, ".factory")
 91→	if err := os.MkdirAll(dir, 0o755); err != nil {
 92→		return fmt.Errorf("mkdir %s: %w", dir, err)
 93→	}
 94→
 95→	settingsPath := filepath.Join(dir, "settings.json")
 96→
 97→	// Read existing settings to merge (hooks may already be configured
 98→	// in the repo-local .factory/settings.json, but the global config
 99→	// at ~/.factory/settings.json might have other pre-existing entries).
100→	var settings droidSettings
101→	if data, readErr := os.ReadFile(settingsPath); readErr == nil {
102→		// Best-effort merge: ignore parse errors and start fresh
103→		_ = json.Unmarshal(data, &settings)
104→	}
105→
106→	// Replace or add the BYOK model entry.
107→	byokModel := droidCustomModel{
108→		DisplayName:    droidCustomModelDisplayName,
109→		Model:          droidCustomModelBaseID,
110→		BaseURL:        "https://api.anthropic.com",
111→		APIKey:         apiKey,
112→		Provider:       "anthropic",
113→		MaxOutputToken: 8192,
114→	}
115→
116→	found := false
117→	for i, m := range settings.CustomModels {
118→		if m.Model == byokModel.Model {
119→			settings.CustomModels[i] = byokModel
120→			found = true
121→			break
122→		}
123→	}
124→	if !found {
125→		settings.CustomModels = append(settings.CustomModels, byokModel)
126→	}
127→
128→	data, err := json.MarshalIndent(settings, "", "  ")
129→	if err != nil {
130→		return fmt.Errorf("marshal settings: %w", err)
131→	}
132→	return os.WriteFile(settingsPath, data, 0o644)
133→}
